const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const roi = ee.Geometry.Point([31.821, 31.517]).buffer(5000); // Damietta mouth, 5km buffer
    const dateRange1984 = ee.DateRange('1984-06-01', '1984-09-30');
    const dateRange2021 = ee.DateRange('2021-06-01', '2021-09-30');

    // Helper function for cloud masking Landsat Collection 2
    function maskL457sr(image) {
        const qa = image.select('QA_PIXEL');
        // Cloud, cloud shadow, and water bits
        const cloudShadowBitMask = (1 << 4);
        const cloudsBitMask = (1 << 3);
        const waterBitMask = (1 << 7);
        const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
            .and(qa.bitwiseAnd(cloudsBitMask).eq(0))
            .and(qa.bitwiseAnd(waterBitMask).eq(0)); // Masking water to focus on land vegetation
        return image.updateMask(mask).select(['SR_B4', 'SR_B3']).rename(['NIR', 'RED']);
    }

    function maskL89sr(image) {
        const qa = image.select('QA_PIXEL');
        const cloudShadowBitMask = (1 << 4);
        const cloudsBitMask = (1 << 3);
        const waterBitMask = (1 << 7);
        const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
            .and(qa.bitwiseAnd(cloudsBitMask).eq(0))
            .and(qa.bitwiseAnd(waterBitMask).eq(0));
        return image.updateMask(mask).select(['SR_B5', 'SR_B4']).rename(['NIR', 'RED']);
    }

    // Helper function to calculate NDVI
    function addNDVI(image) {
        const ndvi = image.normalizedDifference(['NIR', 'RED']).rename('NDVI');
        return image.addBands(ndvi);
    }

    // 2. Data Acquisition & Check
    const collection1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(roi)
        .filterDate(dateRange1984)
        .map(maskL457sr);

    const collection2021 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(roi)
        .filterDate(dateRange2021)
        .map(maskL89sr);

    const size1984 = collection1984.size().getInfo();
    const size2021 = collection2021.size().getInfo();

    if (size1984 === 0 || size2021 === 0) {
        console.log(`Image count 1984: ${size1984}`);
        console.log(`Image count 2021: ${size2021}`);
        console.log("C1: Empty Collection");
        return;
    }

    // 3. Processing
    const image1984 = collection1984.map(addNDVI).median().clip(roi);
    const image2021 = collection2021.map(addNDVI).median().clip(roi);

    const scale = 1000;

    // 4. Calculation & Validation
    const stats1984 = image1984.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
    });

    const stats2021 = image2021.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: roi,
        scale: scale,
        maxPixels: 1e9
    });

    const ndvi1984 = stats1984.get('NDVI').getInfo();
    const count1984 = stats1984.get('NDVI_count').getInfo();
    const ndvi2021 = stats2021.get('NDVI').getInfo();
    const count2021 = stats2021.get('NDVI_count').getInfo();

    if (count1984 === 0 || count2021 === 0) {
        console.log(`Valid pixels 1984: ${count1984}`);
        console.log(`Valid pixels 2021: ${count2021}`);
        console.log("C2: No Valid Pixels");
        return;
    }

    if (ndvi1984 === null || ndvi2021 === null) {
        console.log(`NDVI 1984: ${ndvi1984}`);
        console.log(`NDVI 2021: ${ndvi2021}`);
        console.log("C3: Calculation Failure");
        return;
    }

    // 5. Final Answer
    console.log(`Mean NDVI 1984: ${ndvi1984.toFixed(4)} (Pixels: ${count1984})`);
    console.log(`Mean NDVI 2021: ${ndvi2021.toFixed(4)} (Pixels: ${count2021})`);

    if (ndvi1984 > ndvi2021) {
        console.log("A");
    } else {
        console.log("B");
    }
}

async function initEE() {
    try {
        await new Promise((resolve, reject) => {
            ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
        });
        await new Promise((resolve, reject) => {
            ee.initialize(null, null, resolve, reject);
        });
        await runAnalysis();
    } catch (e) {
        console.error(`Error: ${e.toString()}`);
        console.log("D");
    }
}

initEE();
